update programas_base set instrucciones_terapeuta = replace(instrucciones_terapeuta, '"¿Cuál va con este?" o "Junta este con su pareja"', '"Toca el igual" (o "Pon con el igual" si el alumno coloca la tarjeta)')
  where clinica_id is null and nombre like 'Transferir Funciones%';
update programas_base set instrucciones_terapeuta = replace(instrucciones_terapeuta, '"¿Cuál va con este?"', '"Toca el igual"')
  where clinica_id is null and nombre like 'Transferir Funciones%';

-- Copias ya importadas en el PEI que aún no tienen consignas
update programas_alumno pa set consignas = pb.consignas
  from programas_base pb where pa.programa_base_id = pb.id and pa.consignas is null and pb.consignas is not null;
update clases_rft c set consignas = cb.consignas
  from clases_rft_base cb, programas_alumno pa
  where c.programa_alumno_id = pa.id and cb.programa_base_id = pa.programa_base_id
    and cb.grupo = c.grupo and cb.nombre = c.nombre and c.consignas is null and cb.consignas is not null;

commit;
